-- Common fixture for PostgreSQL 12 and 17 (runs against POSTGRES_DB = dnt_fixture).
SET client_encoding = 'UTF8';

CREATE SCHEMA sales;

CREATE TYPE order_status AS ENUM ('new', 'paid', 'shipped', 'cancelled');

CREATE TABLE public.customers (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name varchar(100) NOT NULL,
  email varchar(255) NOT NULL UNIQUE,
  created_at timestamp NULL
);

CREATE TABLE public.orders (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id integer NOT NULL REFERENCES public.customers (id),
  status order_status NOT NULL DEFAULT 'new',
  total numeric(12,2) NOT NULL DEFAULT 0 CHECK (total >= 0),
  created_at timestamp NULL
);
CREATE INDEX idx_orders_customer_status ON public.orders (customer_id, status);

CREATE TABLE public."đơn_hàng" (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ten varchar(100) NOT NULL,
  ghi_chu text NULL
);

CREATE TABLE public.weird_names (
  id integer PRIMARY KEY,
  "we'ird""col" varchar(50) NULL
);

CREATE TABLE public.bin_blob (
  id integer PRIMARY KEY,
  data bytea NOT NULL
);

CREATE TABLE public.all_types (
  id integer PRIMARY KEY,
  c_smallint smallint NULL,
  c_int integer NULL,
  c_bigint bigint NULL,
  c_numeric numeric(40,10) NULL,
  c_real real NULL,
  c_double double precision NULL,
  c_boolean boolean NULL,
  c_date date NULL,
  c_time time NULL,
  c_timestamp timestamp NULL,
  c_timestamptz timestamptz NULL,
  c_interval interval NULL,
  c_char char(10) NULL,
  c_varchar varchar(255) NULL,
  c_text text NULL,
  c_bytea bytea NULL,
  c_uuid uuid NULL,
  c_json json NULL,
  c_jsonb jsonb NULL,
  c_int_array integer[] NULL,
  c_text_array text[] NULL,
  c_enum order_status NULL
);

CREATE TABLE sales.invoices (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  order_id integer NOT NULL REFERENCES public.orders (id),
  amount numeric(12,2) NOT NULL,
  amount_with_tax numeric(12,2) GENERATED ALWAYS AS (round(amount * 1.1, 2)) STORED,
  tags text[] NULL,
  meta jsonb NULL,
  issued_at timestamptz NOT NULL DEFAULT now(),
  ttl interval NULL
);

CREATE TABLE sales.measurements (
  id integer NOT NULL,
  taken_at date NOT NULL,
  value numeric NULL,
  PRIMARY KEY (id, taken_at)
) PARTITION BY RANGE (taken_at);
CREATE TABLE sales.measurements_2024 PARTITION OF sales.measurements
  FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE sales.measurements_2025 PARTITION OF sales.measurements
  FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');

CREATE SEQUENCE sales.seq_inv START WITH 1000 INCREMENT BY 1;

