CREATE VIEW public.v_customer_orders AS
  SELECT c.id AS customer_id, c.name AS customer_name, o.id AS order_id, o.status, o.total
  FROM public.customers c JOIN public.orders o ON o.customer_id = c.id;

CREATE MATERIALIZED VIEW sales.mv_order_totals AS
  SELECT customer_id, sum(total) AS total_spent, count(*) AS order_count
  FROM public.orders GROUP BY customer_id;

CREATE FUNCTION public.f_add(a integer, b integer) RETURNS integer
  LANGUAGE sql IMMUTABLE AS $$ SELECT a + b $$;

CREATE PROCEDURE public.p_noop()
  LANGUAGE plpgsql AS $$ BEGIN END $$;

CREATE FUNCTION public.fn_orders_bi() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  NEW.created_at := COALESCE(NEW.created_at, now());
  RETURN NEW;
END
$$;

CREATE TRIGGER trg_orders_bi BEFORE INSERT ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.fn_orders_bi();

CREATE ROLE dnt_limited LOGIN PASSWORD 'dnt_test';
GRANT CONNECT ON DATABASE dnt_fixture TO dnt_limited;
GRANT USAGE ON SCHEMA public TO dnt_limited;
GRANT SELECT ON public.customers TO dnt_limited;
